/**
 * The workspace lock: while a subscription is not in good standing the
 * workspace is read-only. `lockReasonFor` is the pure rule; the service layer
 * enforces it through `assertWorkspaceWritable`.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded";

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only (${reason}); update billing to continue`);
    this.name = "WorkspaceLockedError";
  }
}

export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;
  const at = now.getTime();

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return at >= Date.parse(subscription.currentPeriodEnd)
        ? "trial_ended"
        : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return at >= Date.parse(subscription.cancelAt) ? "canceled" : null;
  }
}
